source='''from collections import Counter


def transform(grid):
    """Decode the 30x30 noisy grid into one value per 3x3 cell."""
    out = []
    for br in range(len(grid) // 3):
        row = []
        for bc in range(len(grid[0]) // 3):
            markers = [
                grid[r][c]
                for r in range(br * 3, br * 3 + 3)
                for c in range(bc * 3, bc * 3 + 3)
                if grid[r][c] not in (0, 5)
            ]
            row.append(Counter(markers).most_common(1)[0][0] if markers else 0)
        out.append(row)
    return out
'''
